<template>
	<d2-container>
		<div>
			<div v-if="nowView===1">
				<div>
				 <el-button type="primary" icon="el-icon-refresh" size="medium" @click="getTableData()" >刷新 </el-button>
					<el-button  type="success" icon="el-icon-circle-plus-outline" size="medium" @click="goToAdd()">新建</el-button>
					<el-button  type="success" icon="el-icon-circle-plus-outline" size="medium" @click="goToAdd2()">新建多个</el-button>
					<el-button  type="danger" icon="el-icon-delete" size="medium" @click="deletehw"
					 v-loading.fullscreen.lock="fullscreenLoading">删除</el-button>
					<el-input style="margin-left:30px;width: 150px;" size="medium" placeholder="输入商品名称" v-model="searchFilter.name" prefix-icon="el-icon-search"
					 clearable ></el-input>
					  <!-- <el-select v-model="searchFilter.name" filterable placeholder="选择商品名称" style="margin-left:30px;width: 150px;" size="medium">
                       <el-option
                       v-for="item in cpList"
                       :key="item.value"
                        :label="item.产品名称"
                       :value="item.产品ID">
                     </el-option>
                        </el-select> -->		
					<el-button style="margin-left:5px; margin-top:10px;" type="primary" icon="el-icon-search" size="medium" plain @click="handleSearch">搜索</el-button>
				<!--	<el-button  style="margin-top:10px;" type="primary" icon="el-icon-zoom-out" size="medium" plain @click="clearFilter()">清空条件</el-button> -->
				    <el-button type="primary" icon="el-icon-printer" size="medium"  @click="djdy()">打印</el-button>
                    <el-button   type="info" icon="el-icon-download" size="medium" @click="exportDataEvent">导出</el-button>
				</div>
                  
				 <vxe-table style="margin-top: 10px;" border stripe resizable highlight-hover-row highlight-current-row align="center"  
				 :height="tableHeight" :loading="loading" row-id="id" :print-config="{}"  :data="tableData"   :expand-config="{accordion: true , iconOpen: 'fa fa-minus-square', iconClose: 'fa fa-plus-square' }" ref="xTable1" id="dy1">
					<vxe-table-column type="checkbox" width="60"></vxe-table-column>
					<vxe-table-column  title="操作" width="80">
						<template v-slot="{ row }">
							<el-button type="warning" plain size="small" @click="goToEdit(row)">编辑</el-button>
						</template>
					</vxe-table-column> 
					<vxe-table-column type="seq" width="50" title="序号"></vxe-table-column>
					<vxe-table-column field="id" title="id" :visible="false"></vxe-table-column>
					<vxe-table-column field="货位号" title="货位号" ></vxe-table-column>
					<vxe-table-column field="库房名称" title="库房名称" :visible="false"></vxe-table-column>
					<!-- <vxe-table-column field="条码" title="条码" > 
					<template #default="{ row }">
                       
                       </template>
					</vxe-table-column> -->
					<!-- <vxe-table-column field="规格" title="规格"></vxe-table-column> 
					<vxe-table-column field="型号" title="型号"  width="80"></vxe-table-column> 
					<vxe-table-column field="类型" title="类型"></vxe-table-column>
					<vxe-table-column field="单位" title="单位" width="80"></vxe-table-column> 
					<vxe-table-column field="预警数量" title="预警数量"></vxe-table-column> -->
				</vxe-table>
				<vxe-pager :loading="loading" :current-page="tablePage.currentPage" :page-size="tablePage.pageSize" :total="tablePage.totalResult"
				 :layouts="['PrevPage', 'JumpNumber', 'NextPage', 'FullJump', 'Sizes', 'Total']" @page-change="handlePageChange">
				</vxe-pager> 
                 <el-button  style="margin-left:10px;" type="success" icon="el-icon-s-check" size="medium" plain @click="xzsj" v-show="false">确定</el-button>
			<el-dialog  :visible.sync="dialogTableVisible"  width="65%" @opened="printEvent1">
			<div slot="title" class="dialog-footer" >
           <el-button @click="dialogTableVisible = false">取 消</el-button>
          <el-button type="primary" @click="printEvent1">打 印</el-button>
		  <!-- <div id="myPrint6">           
            <p>将当前渲染的<span style="color: #20f320">内容</span>打印出来，仅<span style="color: blue;font-size: 20px">打印</span>内联<span style="color: red">样式</span></p>
            <p>内容<span style="font-size: 30px;font-weight: 700">区域</span></p>
          </div> -->
           </div>
		   <div ref="print"  id="myPrint5"  media='print' style='font-family:\\5B8B\\4F53'>
            <div v-for="(item,index) in tableData"  :key="index"    v-show="isShow" >
				<div v-if="index%3 == 0"  ref="print2">
					<div style='width:60%;margin:0 auto;text-align: center;'>
			<h1 style='padding: 12px 0px 34px 0;' id="djmz">采购单</h1>
			<!-- <div style='float:right;    font-size: 14px;font-weight: 800;'>页码:{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</div> -->
			</div> 
                 
				<table  border='0' style='width:100%;' id='printtable1'>					
					      	<tr height='30px;'>
					        <td style='text-align:left;'>入库单号：<span id=''>{{item.id}}</span></td>
					        <td style='text-align:center;'>单位名称：<span id=''>{{item.住址}}</span></td> 
					    </tr>                        
					    </table> 
				<table  border='1'  style='width:100%; display:inline-table;border-collapse: collapse;' id='printtable2'>
					    <tr height='40px;'>
							<td style='text-align:center;width:10%'>序号</td>
					        <td style='text-align:center;width:20%'>姓名</td>
					        <td style='text-align:center;width:20%'>联系方式</td> 
					        <td style='text-align:center;width:20%'>照片</td> 
					        <td style='text-align:center;width:30%'>住址</td> 
					    </tr>
					    <tr height='40px;' v-for="(ite,ind) in tableData.slice(index,index+3)" :key="ind">
							<td style='text-align:center;'>{{ind}}</td>
					        <td style='text-align:center;'>{{ite.用户名}}</td>
					        <td style='text-align:center;'>{{ite.联系方式}}</td>
					        <td style='text-align:center;'>{{ite.照片}}</td>
					        <td style='text-align:center;'>{{ite.住址}}</td>
					    </tr>	
		         </table>
				 <table  border='0' style='width:100%;' id='printtable4' >		 							   
		  		   <tr height='30px;'>
					     <td style='text-align:left;'>页码:<span id=''>{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</span></td>
					     <td style='text-align:center;'><span id=''></span></td>
					     <td style='text-align:right;'>金额合计(大写):</td> 
		                 <!-- <td style='text-align:left;'>&nbsp;<span id=''>{{setter.ToString(zje.toFixed(2))}}</span></td>  -->
					     <!-- <td style='text-align:center;'>￥:&nbsp;<span id=''>{{}}</span></td>  -->
			      </tr>	
		 		</table>  
				<table  border='0' style='width:100%;' id='printtable3'>
			          <tr height='30px;'>
					     <td style='text-align:left;'>制单：<span id=''>{{item.id}}</span></td>
					     <td style='text-align:center;'>保管员：<span id=''>{{item.用户名}}</span></td>
					     <td style='text-align:right;'>入库日期：<span id=''>{{item.照片}}</span></td> 
			      </tr>			      
			   </table> 
			   
          
				<div style='page-break-after:always;'></div>
			</div>
			</div> 
			</div>
			</el-dialog>
			<el-dialog  title="货位编辑" :visible.sync="dialogVisible"  width="65%" >
			 <el-form :model="form">
    <el-form-item label="货位号" :label-width="formLabelWidth">
      <el-input v-model="form.hwhm" autocomplete="off"></el-input>
    </el-form-item>
    <!-- <el-form-item label="库房名称" :label-width="formLabelWidth">
      <el-input v-model="form.kfmc" autocomplete="off"></el-input>
    </el-form-item> -->
	<el-form-item label="id" :label-width="formLabelWidth" v-show="false">
      <el-input v-model="form.id" autocomplete="off"></el-input>
    </el-form-item>
  </el-form>
  <div slot="footer" class="dialog-footer">
    <el-button @click="dialogVisible = false">取 消</el-button>
    <el-button type="primary" @click="onSubmit" v-show="xz">新 增</el-button>
	<el-button type="primary" @click="onSubmit2" v-show="xg">修 改</el-button>
  </div>
			</el-dialog>
			 <el-dialog  title="新增货位" :visible.sync="dialogVisible2"  width="65%" ref="xzhw">
			 <el-form :model="form">
    <el-form-item label="货位前缀" :label-width="formLabelWidth">
      <el-input v-model="form.hwqz" autocomplete="off"></el-input>
    </el-form-item>
     <el-form-item label="货位行数" :label-width="formLabelWidth" :rules="rules.hwhs" prop="hwhs">
      <el-input v-model="form.hwhs" autocomplete="off"></el-input>
    </el-form-item> 
	<el-form-item label="货位列数" :label-width="formLabelWidth"  :rules="rules.hwls" prop="hwls">
      <el-input v-model="form.hwls" autocomplete="off"></el-input>
    </el-form-item>
  </el-form>
  <div slot="footer" class="dialog-footer">
    <el-button @click="dialogVisible2 = false">取 消</el-button>
    <el-button type="primary" @click="Submit22">确 定</el-button>
  </div>
			</el-dialog>
			</div>
			
          
			
		

		</div>
	</d2-container>
	
</template>
<script>
    import jsbarcode from 'jsbarcode'
    import printJS from 'print-js'
    import { mapState, mapActions } from 'vuex'
	import setter from '@/libs/setter.js'
	//import Print from './plugin/print/Print'
	import {
		GetMenuTreeOnAuth,
	} from '@api/sys.login.js'
    import {
		Query,
		Aud
	} from '@api/shuju.js'

	export default {
		name: 'HwInfo',
		components: {
			
		},
		data() {
			return {
				fullscreenLoading: false,
				nowView: 1, //当前视图：1是列表，2是编辑页面
				authKeys: [], //用户的权限数组
				tableHeight: 0, //表格高度
				tableData: [], //表内数据	相当于layuidata	
				childData: [],	//子表数据	相当于soulTable子表		
				loading: false, //是否显示加载中
				tablePage: { // 分页属性---
					currentPage: 1, //当前页 相当于layui的page
					pageSize: 10,  	//每页条数 相当于layui的limt
					totalResult: 0  //总页数   相当于count				
				},
				isShow:true,
				TFList: [{
						label: '是',
						value: true
					},
					{
						label: '否',
						value: false
					}
				],
				path:'',
				gnqx:[],
				riqi:'',
				uname:'',
				khList:[],
				cpList:[],
				//搜索变量
				searchFilter: {
					name: '',
					//account: '',
					disable: ''
				},
				form:{
                  hwhm:'',
				  kfmc:'',
				  id:'',
				  hwqz:'',
				  hwhs:'',
				  hwls:''
				},
				rules: {
                  hwhs: [
                   { required: true, message: '请输入行数', trigger: 'blur' },
				   // { type: 'number', message: '行数必须为数字值'}
                  ],
				  hwls: [
                   { required: true, message: '请输入列数', trigger: 'blur' },
				   // { type: 'number', message: '列数必须为数字值'}
                  ],
			},
				xz:false,
				xg:false,
				 formLabelWidth: '120px',
				disables: [{
					'value': '是'
				}, {
					'value': '否'
				}],

                 dialogTableVisible: false,
                 dialogVisible:false,
				 dialogVisible2:false,
				passID: null,

				//批量复制权限
				authCopy: {
					dialogVisible: false,
					userOptions: [],
					form: {
						selectUserID: ''
					},
				
					rules: {
						selectUserID: [{
							required: true,
							message: '请选择用户',
							trigger: 'change'
						}]
					}
				},

			}
		
		},
		created() {
			//this.getAuthKeys()
			//this.getkhData()
			this.getTableData()
		},
		mounted() {
			this.autoTableHeight()
		},
	
		methods: {
			
            
			
			//表格根据浏览器调整高度---
			
			autoTableHeight() {
				
			//	console.log(this.$store.state.d2admin.page)
				
			//	console.info(this.$store.state.d2admin.page.current)
				
				//console.log(this.$store.state.d2admin.user.info.name)
				this.tableHeight = window.innerHeight - 235;
				window.onresize = () => {
					return (() => {
						this.tableHeight = window.innerHeight - 235;
					})();
				};
				
			},
			

             getkhData() {
				
               Query({
							tj:true,
							tablename:'客户',
							field:'id'
						})
						.then(res => {
							//this.tableData = res.data()
							//console.log(res.data)
							this.khList = res.data							 							
						})
						.catch(err => {
							// 异常情况
							
						})
			 }, 
		/* 	  getcpData() {
               Query({
							tj:true,
							tablename:'产品',
							field:'id'
						})
						.then(res => {
							//this.tableData = res.data()
							//console.log(res.data)
					    this.cpList = res.data	
                        this.tableData = res.data
						this.tablePage.totalResult = res.count
						this.loading = false						 							
						})
						.catch(err => {
							// 异常情况
							
						})
			 },   */
			getAuthKeys() {
            let sj =   JSON.parse(window.localStorage.getItem('d2admin-1.7.2'))
			 let info = sj.sys.user.用户.user.info
			 if(info.name == 'admin'){
							let qx;
                      	Query({
							tablename:'菜单',
							columns:'二级菜单',
							field:'id',
							tj:true,
						})
						.then(resl => {
							 qx  = resl.map(function (v,){
								return v.二级菜单
							})
							console.log(qx);
						this.authKeys = qx
						this.getTableData()
						this.uname = info.name
						}).catch(err => {})
						}else{
				GetMenuTreeOnAuth({
                  username:info.name
				})
					.then(res => {			
                         this.authKeys = res.功能权限		
						console.log(this.authKeys);
						this.getTableData()
						this.uname = info.name

					})
					.catch(err => {})
						}
			},
			 getTableData() {
					let tjx	
					let tjy	
					let tjz
					let tjw
					let tj 

					
	
					this.loading = true

				 if(this.searchFilter.name !='' && this.searchFilter.name != null ){
					tjx =`产品名称 like '%${this.searchFilter.name}%'`	
					//tj += ' and ' + tjx
					}else{
						tjx = true
						//tj += ' and ' + tjx 
					}
				
					
					Query({

							limit: this.tablePage.pageSize,
							page: this.tablePage.currentPage,
							tj:tjx,
							tablename:'货位',
							field:'id',
						})
						.then(res => {							
						this.cpList = res.data
						this.tableData = res.data
						this.tablePage.totalResult = res.count
						this.loading = false
							
							
						})
						.catch(err => {
							// 异常情况
							this.loading = false
						})
				
			   
			}, 
			xzsj(){
                let sj = this.$refs.xTable1.getCheckboxRecords()
               console.log( this.$refs.xTable1.getCheckboxRecords() )
               this.$refs.xTable1.insertAt(sj,-1)
            },  
			handleSearch() {
                this.loading = true
				this.tablePage.currentPage = 1 //注意要回来第一页
				this.getTableData()
			},
			handlePageChange({
				currentPage,
				pageSize
			}) {
				this.tablePage.currentPage = currentPage
				this.tablePage.pageSize = pageSize
				this.getTableData()
			},
			clearFilter() {
				let obj = this.searchFilter
				for (let key in obj) {
					this.searchFilter
					obj[key] = null
				}
			},

			exportDataEvent() {
				this.$refs.xTable1.exportData({
					type: 'csv'
				})
			},
             goToAdd(){
				this.dialogVisible = true
				this.xz = true
				this.xg = false
				 /* const $grid = this.$refs.xTable1
               $grid.insert({}) */
			 },
			 goToAdd2(){
				this.dialogVisible2 = true
				//this.xz = true
				//this.xg = false
				 /* const $grid = this.$refs.xTable1
               $grid.insert({}) */
			 },
			 goToEdit(row){
				 console.log(row)
				 this.dialogVisible = true
				 this.xg = true
				 this.xz = false
				 this.form.hwhm = row.货位号
				 this.form.id = row.id
			 },
			 onSubmit(){
			
			   Aud({     //后台数据提交
					 reqType:'append',
					content:[{
							货位号:this.form.hwhm,
						 }],
				    tablename:'货位',
					//order : 'desc'
									})
								.then(result31 => {	
								this.getTableData()
								this.form.hwhm = ''
				                this.form.id = ''
								this.$message.success('货位已增加')
									
								}).catch(err => {
									//this.fullscreenLoading = false
								}) 
				 
					this.dialogVisible = false
			 },
			  onSubmit2(){

					 Aud({
							reqType:'update',
					            content:[{
									货位号:this.form.hwhm,
									id: this.form.id,
								}],
					            tablename:'货位'
							
						})
						.then(res => {
							this.getTableData()
							this.form.hwhm = ''
				            this.form.id = ''
							this.$message.success('货位修改成功')
						})
						.catch(err => {})
				 
					this.dialogVisible = false
			 },
			 Submit22(){
				 let hsz = []
				 let hlz = []
				 let hs
				 let hl
				 let hwbh = []
				 if(this.form.hwhs !='' && this.form.hwls !=''){
                   for (let i = 0; i < this.form.hwhs; i++) {
					if(i<9){
                       hs = '0'+ (i+1).toString()
					}else{
						hs = (i+1).toString()
					}
					//console.log(hs)
					hsz.push(hs)
					
				}
				 for (let ix = 0; ix < this.form.hwls; ix++) {
					if(ix<9){
                       hl = '0'+ (ix+1).toString()
					}else{
						hl = (ix+1).toString()
					}
					//console.log(hl)
					hlz.push(hl)
					
				}
				  hsz.forEach(v =>{
					hlz.forEach(val =>{
					if(this.form.hwqz !=''){
					hwbh.push({货位号:this.form.hwqz + v + val})	
					}else{
						hwbh.push({货位号:v + val})	
					}
					})
				})
				console.log(hwbh)
				this.fullscreenLoading = true
					Aud({     //后台数据提交
					 reqType:'append',
					content:hwbh,
				    tablename:'货位',
					//order : 'desc'
						})
						.then(result31 => {	
								this.fullscreenLoading = false
								this.form.hwhs = ''
								this.form.hwls = ''
				                this.form.hwqz = ''
								this.$message.success('货位已增加')
								this.dialogVisible2 = false	
						}).catch(err => {
							this.fullscreenLoading = false		
								}) 
				
				//this.dialogVisible2 = false
				 }else{
					 this.$message.warning('请输入货位行数和货位列数')
				 }
				 
			 },
			//用户删除
         deletehw() {
				let selectRecords = this.$refs.xTable1.getCheckboxRecords()
				let tempIDs = []
				for (let i = 0; i < selectRecords.length; i++) {
					let sr = selectRecords[i]
					tempIDs.push(sr.id)
					console.log(tempIDs)
				}
				if (tempIDs.length > 0) {
					this.$confirm('确定要永久删除这' + tempIDs.length + '行?', '提示', {
						confirmButtonText: '确定',
						cancelButtonText: '取消',
						type: 'warning'
					}).then(() => {
						this.fullscreenLoading = true
						Aud({
								//id: tempIDs.join(',')
						reqType:'delete',
						content:tempIDs,
						tablename:'货位'
							})
							.then(res => {
								this.fullscreenLoading = false
								this.getTableData()
								this.$message.success('删除成功')
							})
							.catch(err => {
								this.fullscreenLoading = false
							})
					}).catch(() => {});
				} else {
					this.$message.warning('请先勾选要删除的行')
				}
			},
 
            djdy(){
				const printStyle = `
              .bar-code {
                display: inline-block;
                width: 100%;
                height: 140px;
                float: left;
                text-align: center;
              }
              `
              // 打印模板
              const printTmpls = []
			  let dysj = this.$refs.xTable1.getCheckboxRecords()
			  let tempIDs = []
				for (let i = 0; i < dysj.length; i++) {
					let sr = dysj[i]
					tempIDs.push(sr.id)
					console.log(tempIDs)
				}
				if (tempIDs.length > 0) {

				
              dysj.forEach(item => {
                const img = document.createElement('img')
                // 生成条形码
                jsbarcode(img, item.货位号, {
                  lineColor: '#000',
                  width: 2,
                  height: 80,
                 displayValue: true
                })
                const tmpl = `
                <div class="bar-code">                 
                  ${img.outerHTML}
                </div>
                `
                printTmpls.push(tmpl)
              })
              this.$XPrint({
                sheetName: '货位条形码',
                style: printStyle,
                content: printTmpls.join('')
              })
            }else{
					this.$message.warning('请先勾选要打印的行')
				}

          
